class Process(object):
    """Represents an OS process"""
    def __init__(self, pid):
        self._procinfo = ProcessInfo(pid)
        self.is_proxy = True

    def deproxy(self):
        if self.is_proxy:
            self._procinfo = _platform_impl.get_process_info(self._procinfo.pid)
            self.is_proxy = False

    def get_pid(self):
        return self._procinfo.pid

    def get_name(self):
        self.deproxy()
        return self._procinfo.name

    def get_path(self):
        self.deproxy()
        return self._procinfo.path

    # TODO: provide an interface to the sig argument of the underlying
    # method
    def kill(self):         
        _platform_impl.kill_process(self.pid)

    def __str__(self):
        try:
            return "psutil.Process [PID: %s; NAME: '%s'; PATH: '%s']" % (self.pid,  self.name, self.path)
        except:
            #FIXME:  Probably a permission error
            return "psutil.Process [PID: %s; NAME: '?'; PATH: '?']" % self.pid

    pid = property(get_pid)
    name = property(get_name)
    path = property(get_path)
